export const dictionaries: Record<Locale, Dictionary> = { en, de, fr, it, es, ru, tr, ko, ja, zh, vi, th, id, pt, ar };

export function getDictionary(locale: string): Dictionary {
  if ((locales as readonly string[]).includes(locale)) return dictionaries[locale as Locale];
  return en;
}
